      months.map(function (x) { return '<tr><td>' + MONTHS[x.m] + ' ' + x.ym.slice(0, 4) + '</td><td class="num">' + x.j + '</td><td class="num">' + x.l + '</td><td class="num">' + x.c + '</td></tr>'; }).join('') + '</tbody></table></div></details>';
