    h += '<div class="toolbar" role="search"><label class="sr" for="casesQ">Search cases</label><input class="search" id="casesQ" type="search" placeholder="Search name, role, location, case no…" value="' + esc(stC.q) + '" data-inp="cases-q" data-fid="casesQ">' +
      '<label class="sr" for="cfType">Type</label><select class="select" id="cfType" data-chg="cases-f" data-k="type" data-fid="cfType">' + opt('', 'All types', stC.type) + opt('joiner', 'Joiners', stC.type) + opt('leaver', 'Leavers', stC.type) + opt('change', 'Changes', stC.type) + '</select>' +
      '<label class="sr" for="cfCo">Company</label><select class="select" id="cfCo" data-chg="cases-f" data-k="company" data-fid="cfCo">' + opt('', 'All companies', stC.company) + D.COMPANIES.map(function (c) { return opt(c.id, c.label, stC.company); }).join('') + '</select>' +
      '<label class="sr" for="cfLoc">Location</label><select class="select" id="cfLoc" data-chg="cases-f" data-k="loc" data-fid="cfLoc">' + opt('', 'All locations', stC.loc) + locOptions(stC.loc) + '</select>' +
      '<label class="sr" for="cfSt">Status</label><select class="select" id="cfSt" data-chg="cases-f" data-k="status" data-fid="cfSt">' + opt('open', 'Open', stC.status) + opt('overdue', 'Open with overdue tasks', stC.status) + opt('blocked', 'Blocked leavers', stC.status) + opt('closed', 'Closed', stC.status) + opt('all', 'All', stC.status) + '</select></div>';
    h += '<section class="card" aria-label="Case list"><div class="stats" id="casesStats">' + casesStatsHtml(list, odSum) + '</div><div id="casesOut">' + casesTable(list) + '</div></section>';
