      '</div></section>';

    h += '<div class="case-grid"><div><section class="card" aria-labelledby="clH"><div class="card-h"><div><span class="label">' + s.done + ' of ' + s.total + ' done' + (s.over && c.status === 'open' ? ' · <span class="od">' + s.over + ' overdue</span>' : '') + '</span><h2 id="clH">Checklist</h2></div>' +
      '<div class="filters"><div class="seg" role="group" aria-label="Group by"><button type="button" data-act="case-group" data-v="team" aria-pressed="' + (stK.group === 'team') + '" data-fid="cg-team">By team</button><button type="button" data-act="case-group" data-v="date" aria-pressed="' + (stK.group === 'date') + '" data-fid="cg-date">By date</button></div>' +
      '<div class="seg" role="group" aria-label="Show">' + [['all', 'All'], ['open', 'Open'], ['over', 'Overdue'], ['done', 'Done']].map(function (x) { return '<button type="button" data-act="case-show" data-v="' + x[0] + '" aria-pressed="' + (stK.show === x[0]) + '" data-fid="cf-' + x[0] + '">' + x[1] + '</button>'; }).join('') + '</div></div></div>' +
      '<p class="hint" style="margin:0;padding:0 20px 10px">Ticks are recorded as <b style="font-weight:500;color:var(--ink2)">' + esc(actor()) + '</b> (change “Acting as” in the menu). Ticking only records the step: nothing is sent to Microsoft 365, Codeks or payroll.</p>' +
      checklistHtml(c) + '</section></div>';

    // right column: team progress, equipment, activity
