      '<div><span>Manager</span>' + esc(c.manager) + '</div><div><span>Contract</span>' + esc(CONTRACTS[c.contract] || '') + '</div><div><span>Progress</span>' + stats(c).done + ' of ' + stats(c).total + ' done</div><div><span>Status</span>' + STATE[caseState(c)][0] + '</div></div>' +
      '<table><thead><tr><th></th><th>Item</th><th>Team</th><th>Due</th><th>Req.</th><th>Done by</th><th>Initials</th></tr></thead><tbody>' + rows + '</tbody></table>' +
      '<div class="sig"><div>Manager</div><div>HR</div><div>Employee</div></div><div class="ps-foot">Printed ' + fts(nowTs()) + ' (Europe/Ljubljana) · fictional demo data · no ID numbers, bank details or salaries on this sheet.</div></div>';
