        h += '<div class="row2">' + field('Location', '<select class="in" id="%ID%" name="loc">' + locOptions(st.loc) + '</select>') + field('Role', '<select class="in" id="%ID%" name="role">' + roleOptions(kind, st.role) + '</select>') + '</div>';
