          field('Manager', '<select class="in" id="%ID%" name="manager">' + mgrOptions(st.loc, st.manager) + '</select>') +
          field('Contract', '<select class="in" id="%ID%" name="contract">' + Object.keys(CONTRACTS).map(function (k) { return opt(k, CONTRACTS[k], st.contract); }).join('') + '</select>') + '</div>';
