          h += '<div class="row3">' + field('Effective date', '<input class="in" type="date" id="%ID%" name="date" value="' + st.date + '">') + field('Manager from then on', '<select class="in" id="%ID%" name="manager">' + mgrOptions(st.toLoc, st.manager) + '</select>') + tplField + '</div>';
